//! Civitai image + music generation — Generator panel ops (both transports).
//!
//! Pure layer — `reqwest` + the `civitai` client crate + one remote-llm
//! one-shot (music simple-mode drafting), no tauri/axum: BOTH transports
//! (Tauri commands in `commands.rs`, Axum routes in `web.rs`) call these same
//! fns. Identity (`user_id`) is resolved at the transport edge and passed
//! in — the frontend never sends it.
//!
//! Credential model: the Civitai API key is product-baked in
//! `kawai-vault/constants` (`civitai::get_civitai()`, generated by the
//! vault's gen crate). Empty getter = generation unconfigured.
//!
//! Flow: `civitai_generate` submits the recipe endpoint (spends Buzz — the
//! job itself is asynchronous, so the `civitai` client long-polls `?wait=90`
//! and keeps polling the workflow until it turns terminal before returning)
//! then downloads the signed expiring blob URLs and lands the files in the
//! office store (`source_tool: "civitai"`) — they render anywhere
//! `kawai-file://` tokens render. Cost display is the docs' pricing formula
//! computed client-side (the API has no free pricing mode — verified live).

use serde::{Deserialize, Serialize};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{LazyLock, Mutex};
use std::time::{Duration, Instant};

use civitai::{Blob, ImageGenParams};

// ── Token pricing (Buzz → KAWAI token) ─────────────────────────────────────
//
// KAWAI bills usage in app tokens (worker `qris.ts`: `TOKENS_PER_IDR = 100`,
// so 1 token = Rp 0,01). Civitai charges generation in Buzz; its own
// conversion anchor is `BUZZ_PER_USD = 1000` (civitai
// buzz-attribution.service.ts) — 1 Buzz = $0,001. At FX 20.000 IDR/USD that
// is Rp 20 per Buzz = 2.000 tokens; ×1,2 infrastructure margin → 2.400.
// Baked on purpose (repo rule: no env knobs) — keep in sync with the
// frontend twin in `frontend/src/features/generator/ecosystems.ts`.
pub const TOKENS_PER_BUZZ: u64 = 2_400;

/// Convert a Buzz price to app tokens, ALWAYS rounding up — never bill less
/// than the real Buzz spend.
pub fn buzz_to_tokens(buzz: f64) -> u64 {
    (buzz * TOKENS_PER_BUZZ as f64).ceil() as u64
}

/// Image pricing estimate. The image recipes have NO whatif mode (verified
/// live — the parameter is silently ignored), so the price comes from the
/// docs' generation formula (the same one the panel displays):
/// `8 × (W×H/1024²) × (steps/25) × qty`. Upscale passes ride the
/// imageUpscaler recipe (no cost fields either) — each pass doubles the
/// resolution, so a pass is priced at the DOUBLED-dims generation cost
/// (4× the base unit); `txt2img:hires-fix` bills generation + passes,
/// `img2img:upscale` bills passes only. Calibrate against live Buzz spend
/// if civitai reprices.
fn image_buzz_estimate(params: &ImageGenParams) -> f64 {
    let w = params.width as f64;
    let h = params.height as f64;
    let steps = params.steps.unwrap_or(30) as f64;
    let qty = params.quantity.unwrap_or(1) as f64;
    let unit = 8.0 * (w * h / (1024.0 * 1024.0)) * (steps / 25.0) * qty;
    let workflow = params.effective_workflow();
    let generation = if workflow == "img2img:upscale" { 0.0 } else { unit };
    let passes = match workflow {
        "txt2img:hires-fix" | "img2img:upscale" => {
            params.upscale_repeats.unwrap_or(1).max(0) as f64 * 4.0 * unit
        }
        _ => 0.0,
    };
    generation + passes
}

/// Per-process discriminator so two debits inside the same millisecond (the
/// `uuidish()` resolution) never collide on the worker's unique ledger ref.
static DEBIT_SEQ: AtomicU64 = AtomicU64::new(0);

/// Debit the token price off the user's worker balance — FAIL-CLOSED: media
/// spends real Buzz at civitai, so an unreachable worker must block the
/// submit (unlike the LLM turn's fail-open policy). 409
/// `insufficient_balance` arrives as a friendly top-up message.
async fn debit_media_tokens(bearer: &str, tokens: u64) -> Result<(), String> {
    let reference = format!(
        "civitai:{}-{}",
        uuidish(),
        DEBIT_SEQ.fetch_add(1, Ordering::Relaxed)
    );
    match super::topup::billing_debit_ref(bearer, tokens, &reference).await {
        Ok(_) => Ok(()),
        Err(e) if e.contains("insufficient_balance") => Err(format!(
            "Saldo tidak cukup: {tokens} token diperlukan — isi ulang lewat halaman Top Up"
        )),
        Err(e) => Err(format!("debit saldo gagal: {e}")),
    }
}

// ── Wire types (camelCase both directions, like logic::topup) ──────────────

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApiKeyStatus {
    pub configured: bool,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SavedImage {
    pub file_id: String,
    pub name: String,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCover {
    pub ecosystem: String,
    pub label: String,
    /// The model's card art on civitai (CDN URL) — None when the lookup
    /// found nothing; the UI falls back to the gradient tile.
    pub url: Option<String>,
    /// Name of the model that will actually run. Set only for the music
    /// lane's pinned records — the image lane's art is a rating-ranked
    /// search hit, never the checkpoint the orchestrator falls back to, so
    /// naming it would claim a provenance the request doesn't carry.
    pub model_name: Option<String>,
}

/// Top-checkpoint cover art per panel ecosystem (the thing that makes the
/// picker look like civitai's). Public v1 read; cached in-process for 1h —
/// the picker hits this on every panel mount. Cover art rides the LIST
/// payload (`modelVersions[0].images`) — no per-model image calls.
static COVER_CACHE: LazyLock<Mutex<Option<(Instant, Vec<ModelCover>)>>> =
    LazyLock::new(|| Mutex::new(None));
const COVER_TTL: Duration = Duration::from_secs(3600);
/// Panel ecosystem → v1 search query (top Checkpoint by rating).
const COVER_QUERIES: [(&str, &str); 4] = [
    ("anima", "anime"),
    ("sdxl", "sdxl"),
    ("flux1", "flux"),
    ("flux2Klein", "flux klein"),
];

/// The music lane's PINNED models — civitai's audio ecosystems are all
/// `modelLocked`, so the card art comes from the version record, not a
/// search. Sonilo's v1 record carries no card ("Missing model file") — its
/// logo URL is baked (civitai's B2 blob store, civitai.com subdomain, so it
/// rides the worker proxy like every other civitai-hosted URL).
const MUSIC_MODEL_VERSIONS: [(&str, i64, &str, Option<&str>); 4] = [
    ("minimax-music3", 3_225_593, "MiniMax Music", None),
    ("yue2", 3_337_846, "YuE2-3B", None),
    (
        "sonilo",
        3_370_181,
        "Sonilo",
        Some("https://blobs-b2.civitai.com/file/blobs-managed-public/F014CSKHPKMVFT6P0VQPEK5AF0.webp"),
    ),
    ("ace", 2_864_949, "ACE-Step Audio Gen", None),
];

pub async fn civitai_model_covers() -> Result<Vec<ModelCover>, String> {
    if let Some((at, covers)) = COVER_CACHE.lock().ok().and_then(|c| c.clone()) {
        if at.elapsed() < COVER_TTL {
            return Ok(covers);
        }
    }

    let key = kawai_constants::civitai::get_civitai();
    let mut covers = Vec::with_capacity(COVER_QUERIES.len() + MUSIC_MODEL_VERSIONS.len());
    for (ecosystem, query) in COVER_QUERIES {
        let cover = civitai::search_models(&key, query, &["Checkpoint"], 3, Some("Highest Rated"), None)
            .await
            .ok()
            .and_then(|page| {
                page.items.into_iter().find_map(|m| {
                    let url = m
                        .model_versions
                        .as_ref()?
                        .first()?
                        .images
                        .as_ref()?
                        .first()?
                        .url
                        .clone()?;
                    Some(ModelCover {
                        ecosystem: ecosystem.to_string(),
                        label: ecosystem.to_string(),
                        url: Some(url),
                        model_name: None,
                    })
                })
            });
        covers.push(cover.unwrap_or(ModelCover {
            ecosystem: ecosystem.to_string(),
            label: ecosystem.to_string(),
            url: None,
            model_name: None,
        }));
    }
    // Music lane: PINNED models — civitai's audio ecosystems are all
    // `modelLocked`, so the card art comes from the version record, not a
    // search. A failed lookup degrades to the static name with no URL.
    for (ecosystem, version_id, fallback_name, direct_cover) in MUSIC_MODEL_VERSIONS {
        let (model_name, url) = match direct_cover {
            // Card art baked outside the v1 API — just proxy it.
            Some(url) => (
                fallback_name.to_string(),
                civitai::rewrite_civitai_url(url).or_else(|| Some(url.to_string())),
            ),
            None => match civitai::model_version_card(&key, version_id).await {
                Ok((name, url)) => {
                    let name = if name.is_empty() { fallback_name } else { &name };
                    (name.to_string(), url)
                }
                Err(_) => (fallback_name.to_string(), None),
            },
        };
        covers.push(ModelCover {
            ecosystem: ecosystem.to_string(),
            label: ecosystem.to_string(),
            url,
            model_name: Some(model_name),
        });
    }
    if let Ok(mut c) = COVER_CACHE.lock() {
        *c = Some((Instant::now(), covers.clone()));
    }
    Ok(covers)
}

// ── Template gallery (empty-state presets) ─────────────────────────────────

/// One community image preset for the image lane's empty state. Clicking it
/// fills the form with the image's generation config AND its resources —
/// the checkpoint (diffuser override) + LoRA stack, each resolved by hash
/// to civitai's canonical AIR URN and family-gated to the selected
/// ecosystem. The gallery is still not a reproduction: the seed is left
/// random and the builtin diffuser renders when no compatible checkpoint
/// resolved.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplatePreset {
    /// Worker-proxied CDN URL — the webview renders it directly.
    pub url: String,
    pub width: i64,
    pub height: i64,
    pub prompt: String,
    pub negative_prompt: Option<String>,
    pub steps: Option<i64>,
    pub cfg_scale: Option<f64>,
    /// Civitai sampler display name — meaningful on SD-family ecosystems
    /// only; the frontend applies it conditionally.
    pub sampler: Option<String>,
    /// Checkpoint name from meta, when carried — display caption only.
    pub model_name: Option<String>,
    /// The image's checkpoint as a diffuser override, when its family
    /// matches the selected ecosystem — None otherwise (the builtin
    /// diffuser renders).
    pub checkpoint: Option<TemplateResource>,
    /// The image's LoRA stack (≤4), family-gated the same way.
    pub loras: Vec<TemplateResource>,
}

/// One auto-added model reference: a resolved `meta.resources` hash.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplateResource {
    pub name: String,
    /// Civitai's canonical AIR URN, verbatim from the by-hash endpoint.
    pub air_urn: String,
    /// LoRA strength (meta `weight`); checkpoint entries carry none.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub strength: Option<f64>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplateGalleryArgs {
    pub ecosystem: String,
}

/// Panel ecosystem → v1 checkpoint search term (the gallery shows the
/// top-rated checkpoint's showcase for the family; a miss degrades to an
/// empty gallery and the frontend falls back to the plain empty state).
const TEMPLATE_QUERIES: [(&str, &str); 12] = [
    ("anima", "anime"),
    ("sdxl", "sdxl"),
    ("flux1", "flux"),
    ("flux2Klein", "flux klein"),
    ("flux2Dev", "flux dev"),
    ("sd1", "dreamshaper"),
    ("qwen", "qwen image"),
    ("zImageTurbo", "z image"),
    ("zImageBase", "z image"),
    ("wan", "wan"),
    ("seedream", "seedream"),
    ("grok", "grok"),
];

/// Per-ecosystem 1h cache — the empty state hits this on every panel mount
/// and every eco switch, same shape as `COVER_CACHE`.
static TEMPLATE_CACHE: LazyLock<Mutex<std::collections::HashMap<String, (Instant, Vec<TemplatePreset>)>>> =
    LazyLock::new(|| Mutex::new(std::collections::HashMap::new()));
const TEMPLATE_TTL: Duration = Duration::from_secs(3600);

/// Upper bound on copied prompt/negative text — a template fills the form,
/// it must not dump a 10k-char A11-detailer blob into the textarea.
const TEMPLATE_TEXT_CAP: usize = 4000;
/// Per-image LoRA cap (the form's own cap is 9 — templates stay lean).
const TEMPLATE_LORAS_CAP: usize = 4;
/// Hard cap on by-hash calls per gallery refresh — resolution is sequential
/// (no futures dep) and civitai's v1 is rate-limited; a bigger unique-hash
/// set silently skips its leftovers until the next cache expiry.
const TEMPLATE_RESOLVE_BUDGET: usize = 12;

fn cap_text(value: Option<String>) -> Option<String> {
    let trimmed = value?.trim().to_string();
    if trimmed.is_empty() {
        return None;
    }
    Some(truncate_chars(&trimmed, TEMPLATE_TEXT_CAP))
}

/// A by-hash resolution kept across refreshes — hashes repeat heavily
/// (community images cluster on the same checkpoint/LoRAs), so the cache is
/// the thing that keeps the sequential calls bounded in practice.
type ResolvedResource = Option<(String, String, Option<String>)>;
static RESOURCE_CACHE: LazyLock<
    Mutex<std::collections::HashMap<String, (Instant, ResolvedResource)>>,
> = LazyLock::new(|| Mutex::new(std::collections::HashMap::new()));
const RESOURCE_TTL: Duration = Duration::from_secs(24 * 3600);

/// `(air_urn, name, base_model)` for one resources hash — `None` when
/// civitai carries no version for it. Display name comes from the meta
/// resources entry (the by-hash response carries none).
async fn resolve_resource(
    key: &str,
    hash: &str,
    name: &str,
    budget: &mut usize,
) -> Result<ResolvedResource, String> {
    if let Some((at, resolved)) = RESOURCE_CACHE.lock().ok().and_then(|m| m.get(hash).cloned()) {
        if at.elapsed() < RESOURCE_TTL {
            return Ok(resolved);
        }
    }
    if *budget == 0 {
        // Cache miss but the refresh's call budget is spent — report
        // "unknown" WITHOUT caching, so a later refresh resolves it.
        return Ok(None);
    }
    *budget -= 1;
    let resolved = civitai::model_version_by_hash(key, hash)
        .await?
        .map(|v| (v.air.unwrap_or_default(), name.to_string(), v.base_model))
        .filter(|(air, _, _)| !air.is_empty());
    if let Ok(mut cache) = RESOURCE_CACHE.lock() {
        cache.insert(hash.to_string(), (Instant::now(), resolved.clone()));
    }
    Ok(resolved)
}

pub async fn civitai_template_gallery(args: TemplateGalleryArgs) -> Result<Vec<TemplatePreset>, String> {
    let ecosystem = args.ecosystem.trim().to_string();
    if ecosystem.is_empty() {
        return Ok(Vec::new());
    }
    if let Some((at, presets)) = TEMPLATE_CACHE
        .lock()
        .ok()
        .and_then(|m| m.get(&ecosystem).cloned())
    {
        if at.elapsed() < TEMPLATE_TTL {
            return Ok(presets);
        }
    }

    let key = require_key()?;
    let query = TEMPLATE_QUERIES
        .iter()
        .find(|(id, _)| *id == ecosystem)
        .map(|(_, q)| *q)
        .unwrap_or(ecosystem.as_str());

    // Top-rated checkpoint for the family → its first version's showcase
    // feed, reactions-ranked, meta-carrying images only (authors who
    // stripped their generation data are useless as templates).
    let version_id = civitai::search_models(&key, query, &["Checkpoint"], 3, Some("Highest Rated"), None)
        .await
        .ok()
        .and_then(|page| page.items.into_iter().find_map(|m| m.model_versions.and_then(|v| v.first().map(|first| first.id))));
    let Some(version_id) = version_id else {
        if let Ok(mut cache) = TEMPLATE_CACHE.lock() {
            cache.insert(ecosystem, (Instant::now(), Vec::new()));
        }
        return Ok(Vec::new());
    };

    let hits = civitai::search_images(&key, version_id, 40, "Most Reactions", "AllTime").await?;
    // Family gate for auto-attached checkpoint/LoRAs: the AIR may only ride
    // the request when its base-model family equals the ecosystem's own —
    // a cross-family diffuser override would 400 at the orchestrator. The
    // unclassified ecosystems (anima, flux2/zImage, the engines) have no
    // confident mapping, so nothing auto-attaches there — their builtin
    // diffuser is the point of picking them anyway.
    let eco_family = civitai::registry::ecosystem_family(&ecosystem);
    let family_of = |base: &Option<String>| -> Option<&'static str> {
        eco_family.and_then(|eco| base.as_deref().and_then(civitai::registry::base_model_family).and_then(|f| (f == eco).then_some(f)))
    };
    let mut resolve_budget = TEMPLATE_RESOLVE_BUDGET;
    let mut raw: Vec<(civitai::V1ImageHit, civitai::V1ImageMeta)> = Vec::new();
    for hit in hits {
        // SFW double-guard: `nsfw=None` on the wire plus this client-side
        // level filter (the flag maps to a browsing level, not the enum).
        if hit.nsfw_level.as_deref().unwrap_or("None") != "None" {
            continue;
        }
        let Some(meta) = hit.meta.clone() else { continue };
        if raw.len() < 12 {
            raw.push((hit, meta));
        } else {
            break;
        }
    }

    let mut presets: Vec<TemplatePreset> = Vec::with_capacity(raw.len());
    for (hit, meta) in raw {
        let Some(prompt) = cap_text(meta.prompt.clone()) else { continue };
        let Some(url) = hit.url.clone().filter(|u| !u.is_empty()) else { continue };

        // Resources: resolve hashes → AIR, gate each by family.
        let mut checkpoint: Option<TemplateResource> = None;
        let mut loras: Vec<TemplateResource> = Vec::new();
        for entry in meta.resources.iter().flatten() {
            let Some(hash) = entry.hash.as_deref().filter(|h| !h.trim().is_empty()) else { continue };
            let kind = entry.kind.as_deref().unwrap_or("");
            if kind != "model" && kind != "lora" {
                continue; // VAE / embeddings / TI — nothing the form carries
            }
            if kind == "lora" && loras.len() >= TEMPLATE_LORAS_CAP {
                continue;
            }
            if checkpoint.is_some() && kind != "lora" {
                continue; // one checkpoint per template
            }
            let name = entry
                .name
                .clone()
                .filter(|n| !n.trim().is_empty())
                .unwrap_or_else(|| hash.to_string());
            let Ok(Some((air, name, base))) = resolve_resource(&key, hash, &name, &mut resolve_budget).await
            else {
                continue;
            };
            if family_of(&base).is_none() {
                continue;
            }
            let resource = TemplateResource {
                name,
                air_urn: air,
                strength: if kind == "lora" {
                    Some(entry.weight.unwrap_or(1.0).clamp(0.0, 4.0))
                } else {
                    None
                },
            };
            if kind == "lora" {
                loras.push(resource);
            } else {
                checkpoint = Some(resource);
            }
        }

        presets.push(TemplatePreset {
            url,
            width: hit.width.unwrap_or(1024).max(64),
            height: hit.height.unwrap_or(1024).max(64),
            prompt,
            negative_prompt: cap_text(meta.negative_prompt),
            steps: meta.steps,
            cfg_scale: meta.cfg_scale,
            sampler: meta.sampler,
            model_name: meta.model,
            checkpoint,
            loras,
        });
    }

    if let Ok(mut cache) = TEMPLATE_CACHE.lock() {
        cache.insert(ecosystem.clone(), (Instant::now(), presets.clone()));
    }
    Ok(presets)
}

// ── Resource browser (the civitai model-picker modal) ──────────────────────

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SearchModelsArgs {
    /// Target generation ecosystem — the constructed AIR URN carries it,
    /// and rows whose v1 `baseModel` maps to a DIFFERENT known family are
    /// dropped (both sides unclassified = kept, the orchestrator decides).
    pub ecosystem: String,
    #[serde(default)]
    pub query: Option<String>,
    /// `"Checkpoint"` (default) or `"LORA"`.
    #[serde(default)]
    pub model_type: Option<String>,
    /// v1 sort: `"Highest Rated"` (default) | `"Most Downloaded"` | `"Newest"`.
    #[serde(default)]
    pub sort: Option<String>,
    #[serde(default)]
    pub limit: Option<i64>,
    /// Keyset cursor from the previous page (`nextCursor`) — None = page 1.
    #[serde(default)]
    pub cursor: Option<String>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SearchModelPage {
    pub rows: Vec<SearchModelRow>,
    /// None = no more pages.
    pub next_cursor: Option<String>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SearchModelRow {
    pub model_id: i64,
    pub version_id: i64,
    pub name: String,
    pub creator: Option<String>,
    pub downloads: Option<i64>,
    pub thumbs_up: Option<i64>,
    pub base_model: Option<String>,
    pub cover_url: Option<String>,
    /// HTML description stripped to plain text, capped for the grid card.
    pub description: Option<String>,
    /// Up to 3 showcase images BESIDES the cover — the example strip.
    pub example_urls: Vec<String>,
    /// `urn:air:{ecosystem}:{checkpoint|lora}:civitai:{model}@{version}` —
    /// constructed; list payloads do not carry AIR URNs.
    pub air_urn: String,
}

/// Crude HTML→text (tag stripping + whitespace collapse) — descriptions are
/// display-only snippets, never rendered as HTML.
fn strip_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut in_tag = false;
    for ch in s.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            c if !in_tag => out.push(c),
            _ => {}
        }
    }
    out.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn truncate_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    let cut: String = s.chars().take(max).collect();
    format!("{cut}…")
}

pub async fn civitai_search_models(args: SearchModelsArgs) -> Result<SearchModelPage, String> {
    let key = require_key()?;
    let is_lora = matches!(args.model_type.as_deref(), Some("LORA") | Some("lora"));
    let model_type = if is_lora { "LORA" } else { "Checkpoint" };
    let limit = args.limit.unwrap_or(20).clamp(1, 50);
    let page = civitai::search_models(
        &key,
        args.query.as_deref().unwrap_or(""),
        &[model_type],
        limit,
        args.sort.as_deref(),
        args.cursor.as_deref(),
    )
    .await?;
    let next_cursor = page.next_cursor();
    let eco_family = civitai::registry::ecosystem_family(&args.ecosystem);
    let rows = page
        .items
        .into_iter()
        .filter_map(|m| {
            let version = m.model_versions.as_ref()?.first()?;
            let creator = m.creator.and_then(|c| c.username);
            let downloads = m.stats.as_ref().and_then(|s| s.download_count);
            let thumbs_up = m.stats.as_ref().and_then(|s| s.thumbs_up_count);
            // Cover/examples usually ride the FIRST version — but some models
            // only have showcase art on older versions, so scan until found.
            let images = m
                .model_versions
                .as_ref()
                .and_then(|versions| {
                    versions
                        .iter()
                        .find(|v| v.images.as_ref().is_some_and(|imgs| !imgs.is_empty()))
                        .or_else(|| versions.first())
                })
                .and_then(|v| v.images.as_ref())
                .map(|imgs| imgs.iter().filter_map(|i| i.url.clone()).collect::<Vec<_>>())
                .unwrap_or_default();
            let cover_url = images.first().cloned();
            // Example strip: up to 3 showcase images besides the cover.
            let example_urls: Vec<String> = images.into_iter().skip(1).take(3).collect();
            let description = m
                .description
                .as_deref()
                .map(strip_html)
                .filter(|s| !s.is_empty())
                .map(|s| truncate_chars(&s, 220));
            Some(SearchModelRow {
                model_id: m.id,
                version_id: version.id,
                air_urn: format!(
                    "urn:air:{}:{}:civitai:{}@{}",
                    args.ecosystem, kind_segment(is_lora), m.id, version.id
                ),
                name: m.name,
                creator,
                downloads,
                thumbs_up,
                base_model: version.base_model.clone(),
                cover_url,
                description,
                example_urls,
            })
        })
        // Model follows ecosystem: drop rows whose base model maps to a
        // different KNOWN family (either side unclassified = kept — the
        // orchestrator, not a prefix table, has the last word).
        .filter(|row| match (
            eco_family,
            row.base_model
                .as_deref()
                .and_then(civitai::registry::base_model_family),
        ) {
            (Some(a), Some(b)) => a == b,
            _ => true,
        })
        .collect();
    Ok(SearchModelPage {
        rows,
        next_cursor,
    })
}

fn kind_segment(is_lora: bool) -> &'static str {
    if is_lora {
        "lora"
    } else {
        "checkpoint"
    }
}

// ── API key ────────────────────────────────────────────────────────────────

fn require_key() -> Result<String, String> {
    let key = kawai_constants::civitai::get_civitai();
    if key.trim().is_empty() {
        return Err(
            "Civitai API key belum dikonfigurasi di vault (kawai-vault/constants)".to_string(),
        );
    }
    Ok(key)
}

pub fn civitai_api_key_status() -> ApiKeyStatus {
    ApiKeyStatus {
        configured: !kawai_constants::civitai::get_civitai().trim().is_empty(),
    }
}

// ── Generation ─────────────────────────────────────────────────────────────

fn blob_view(b: &Blob) -> Option<&Blob> {
    b.url
        .as_ref()
        .is_some_and(|u| !u.trim().is_empty())
        .then_some(b)
}

/// Generate images and persist them into the user's office store. The
/// recipe call SPENDS Buzz — the panel's Generate click is the consent —
/// and blocks until the job is terminal: the `civitai` client long-polls
/// `?wait=90`, then polls the workflow until it turns terminal (spec
/// defaults finish in 10–25s; large batches run minutes, hence the 180s
/// poll deadline). Each call creates NEW files (import semantics).
/// Submit the image-gen recipe. SPENDS Buzz — the panel's Generate click is
/// the consent. Billing: the docs' formula estimate is debited off the
/// user's token balance BEFORE the submit (fail-closed — no balance, no
/// generation), with the Civitai Buzz charge mirroring it at the baked
/// account.
pub async fn civitai_generate(
    user_id: &str,
    bearer: &str,
    params: ImageGenParams,
) -> Result<Vec<SavedImage>, String> {
    // Validate BEFORE any money moves — a rejected shape must never cost the
    // user a debit (the submit path re-validates; this is the gate).
    params.validate()?;
    debit_media_tokens(bearer, buzz_to_tokens(image_buzz_estimate(&params))).await?;
    let key = require_key()?;
    let result = civitai::submit_image_gen(&key, &params).await?;
    if result.images.is_empty() {
        return Err(result
            .errors
            .and_then(|errs| errs.into_iter().next())
            .unwrap_or_else(|| "Civitai tidak mengembalikan gambar".into()));
    }
    let short_id: String = params.ecosystem.clone() + "-" + &uuidish();
    let mut saved = Vec::with_capacity(result.images.len());
    let mut failed_downloads: Vec<String> = Vec::new();
    for (i, blob) in result.images.iter().filter_map(blob_view).enumerate() {
        let url = blob.url.as_deref().unwrap_or_default();
        let bytes = match civitai::download_bytes(url).await {
            Ok(bytes) => bytes,
            Err(e) => {
                failed_downloads.push(format!("gambar {}: {e}", i + 1));
                continue;
            }
        };
        // Signed URLs end in the real extension (.jpeg/.png); default jpg.
        let ext = if url.split('?').next().is_some_and(|p| p.ends_with(".png")) {
            "png"
        } else {
            "jpg"
        };
        let name = format!("civitai-{short_id}-{}.{}", i + 1, ext);
        let file = kawai_office::store::import_as(
            user_id,
            &name,
            &bytes,
            kawai_office::store::ArtifactKind::Image,
            "civitai",
            None,
        )
        .map_err(|e| format!("gagal menyimpan {name}: {e}"))?;
        saved.push(SavedImage {
            file_id: file.id,
            name,
        });
    }
    if saved.is_empty() {
        return Err(format!(
            "semua unduhan gagal: {}",
            failed_downloads.join("; ")
        ));
    }
    if !failed_downloads.is_empty() {
        eprintln!("civitai: {} unduhan gagal", failed_downloads.join("; "));
    }
    Ok(saved)
}

/// Short per-run discriminator for file names (timestamp-based; the office
/// store mints its own opaque ids — this only keeps names readable).
fn uuidish() -> String {
    let d = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    format!("{d:x}")
}

// ── Video generation (workflows API) ───────────────────────────────────────
//
// Video runs through the workflow surface, not a recipe: the image path
// hides its own polling behind the recipe call, while video hands the
// workflowId back to the panel. submit spends Buzz and returns a
// workflowId; the panel polls
// `civitai_video_status` (server-side long-poll) until a terminal state,
// then `civitai_video_fetch` downloads the signed mp4 ONCE into the office
// store. Restart-safe by design — the workflowId lives client-side, and
// status/fetch are idempotent reads; nothing generation-shaped lives in
// memory between calls.

/// Panel request shape — camelCase from both transports, mapped onto the
/// client's `VideoGenParams`.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VideoGenRequest {
    pub ecosystem: String,
    #[serde(default)]
    pub workflow: Option<String>,
    #[serde(default)]
    pub prompt: Option<String>,
    #[serde(default)]
    pub negative_prompt: Option<String>,
    /// Source frames, ordered: img2vid = [first, (last)]; ref2vid = refs.
    #[serde(default)]
    pub images: Vec<String>,
    /// Source video for `vid2vid:edit` (grok v1.0) — data URL / base64 / URL.
    #[serde(default)]
    pub video: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
    #[serde(default)]
    pub mode: Option<String>,
    #[serde(default)]
    pub fast_mode: Option<bool>,
    #[serde(default)]
    pub duration: Option<i64>,
    #[serde(default)]
    pub resolution: Option<String>,
    #[serde(default)]
    pub aspect_ratio: Option<String>,
    #[serde(default)]
    pub generate_audio: Option<bool>,
    #[serde(default)]
    pub enable_prompt_enhancer: Option<bool>,
    #[serde(default)]
    pub cfg_scale: Option<f64>,
    #[serde(default)]
    pub steps: Option<i64>,
    #[serde(default)]
    pub draft: Option<bool>,
    #[serde(default)]
    pub style: Option<String>,
    #[serde(default)]
    pub movement_amplitude: Option<String>,
    #[serde(default)]
    pub seed: Option<i64>,
    #[serde(default)]
    pub quantity: Option<i64>,
}

impl VideoGenRequest {
    fn to_params(&self) -> civitai::VideoGenParams {
        civitai::VideoGenParams {
            ecosystem: self.ecosystem.clone(),
            workflow: self.workflow.clone(),
            prompt: self.prompt.clone().unwrap_or_default(),
            negative_prompt: self.negative_prompt.clone(),
            images: self.images.clone(),
            video: self.video.clone(),
            model: self.model.clone(),
            mode: self.mode.clone(),
            fast_mode: self.fast_mode,
            duration: self.duration,
            resolution: self.resolution.clone(),
            aspect_ratio: self.aspect_ratio.clone(),
            generate_audio: self.generate_audio,
            enable_prompt_enhancer: self.enable_prompt_enhancer,
            cfg_scale: self.cfg_scale,
            steps: self.steps,
            draft: self.draft,
            style: self.style.clone(),
            movement_amplitude: self.movement_amplitude.clone(),
            seed: self.seed,
            quantity: self.quantity,
        }
    }
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct VideoCostView {
    pub total_buzz: f64,
    /// App-token twin of `total_buzz` (ceil) — what the balance will be
    /// debited at submit. Displayed as the panel's ≈ pill.
    pub total_tokens: u64,
    pub ready: bool,
    pub warnings: Vec<String>,
}

/// Free cost estimate (whatif — no persist, no charge). A failure here means
/// submit would fail too: surface it as the error.
pub async fn civitai_video_cost(req: VideoGenRequest) -> Result<VideoCostView, String> {
    let key = require_key()?;
    let est = civitai::whatif_video_gen(&key, &req.to_params()).await?;
    Ok(VideoCostView {
        total_buzz: est.total_buzz,
        total_tokens: buzz_to_tokens(est.total_buzz),
        ready: est.ready,
        warnings: est.warnings,
    })
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct VideoSubmitView {
    pub workflow_id: String,
}

/// Submit the videoGen workflow. SPENDS Buzz — the panel's Generate click
/// (with the whatif cost displayed) is the consent. The token debit rides
/// the same whatif price and happens BEFORE the submit — fail-closed: media
/// spends real Buzz, so an unreachable/depleted balance must block here,
/// never after the Buzz is gone. Returns the workflowId the panel stores
/// and polls.
pub async fn civitai_video_submit(
    _user_id: &str,
    bearer: &str,
    req: VideoGenRequest,
) -> Result<VideoSubmitView, String> {
    let key = require_key()?;
    let params = req.to_params();
    let est = civitai::whatif_video_gen(&key, &params).await?;
    debit_media_tokens(bearer, buzz_to_tokens(est.total_buzz)).await?;
    let submitted = civitai::submit_video_gen(&key, &params).await?;
    Ok(VideoSubmitView {
        workflow_id: submitted.id,
    })
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct VideoBlobView {
    pub video_url: String,
    pub thumbnail_url: Option<String>,
    pub width: Option<i64>,
    pub height: Option<i64>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct VideoStatusView {
    pub workflow_id: String,
    /// Normalized: `queued` | `processing` | `succeeded` | `failed` |
    /// `expired` | `canceled` (anything else passes through lowercased).
    pub status: String,
    pub queue_position: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub video: Option<VideoBlobView>,
    /// LTX-style batched jobs: extra clips beyond the primary video.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub additional: Vec<VideoBlobView>,
    pub error: Option<String>,
}

/// Poll one workflow (server-side long-poll — the call holds up to
/// `wait_secs`, default 15, before replying with the current snapshot).
pub async fn civitai_video_status(
    workflow_id: String,
    wait_secs: Option<u64>,
) -> Result<VideoStatusView, String> {
    if workflow_id.trim().is_empty() {
        return Err("workflowId kosong".into());
    }
    let key = require_key()?;
    let wf = civitai::video_workflow_status(&key, workflow_id.trim(), wait_secs.unwrap_or(15))
        .await?;
    let status = match wf.status.as_str() {
        "unassigned" | "preparing" | "scheduled" => "queued".to_string(),
        other => other.to_string(),
    };
    Ok(VideoStatusView {
        workflow_id: wf.id,
        queue_position: wf.queue_position,
        video: wf.video_url.map(|video_url| VideoBlobView {
            video_url,
            thumbnail_url: wf.thumbnail_url,
            width: wf.width,
            height: wf.height,
        }),
        additional: wf
            .additional
            .into_iter()
            .map(|m| VideoBlobView {
                video_url: m.url,
                thumbnail_url: m.thumbnail_url,
                width: m.width,
                height: m.height,
            })
            .collect(),
        error: wf.error,
        status,
    })
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SavedVideo {
    pub file_id: String,
    pub name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thumbnail_file_id: Option<String>,
    /// LTX-style batched jobs: the extra clips, imported after the primary.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub additional: Vec<SavedVideo>,
}

/// Cancel a queued/running workflow (`PUT` `{status:"canceled"}` — civitai's
/// own client shape). Best-effort from the panel: the job card's cancel
/// button calls this, then stops polling; the workflow settles `canceled`.
pub async fn civitai_video_cancel(workflow_id: String) -> Result<(), String> {
    let workflow_id = workflow_id.trim().to_string();
    if workflow_id.is_empty() {
        return Err("workflowId kosong".into());
    }
    let key = require_key()?;
    civitai::cancel_video_workflow(&key, &workflow_id).await
}

/// Download the finished video (SIGNED, EXPIRING URL — fetch once) into the
/// office store as `ArtifactKind::Video`, plus its poster thumbnail as an
/// image. Idempotence is the CALLER's job: poll status, and call fetch
/// exactly once per workflow (re-fetching would duplicate files — import
/// semantics always create new entries).
pub async fn civitai_video_fetch(
    user_id: &str,
    workflow_id: String,
    video_url: String,
    thumbnail_url: Option<String>,
    additional_urls: Vec<String>,
) -> Result<SavedVideo, String> {
    let _ = require_key()?; // same baked identity; the URL itself carries the signature
    let workflow_id = workflow_id.trim().to_string();
    if workflow_id.is_empty() || video_url.trim().is_empty() {
        return Err("workflowId dan videoUrl wajib diisi".into());
    }
    let bytes = civitai::download_bytes(video_url.trim())
        .await
        .map_err(|e| format!("unduh video gagal: {e}"))?;
    // Signed URLs end in the real extension; videos are mp4 almost always,
    // webm occasionally.
    let ext = match video_url.split('?').next().and_then(|p| {
        p.rsplit('.')
            .next()
            .map(|e| e.to_ascii_lowercase())
    }) {
        Some(e) if e == "webm" || e == "mov" || e == "m4v" => e,
        _ => "mp4".to_string(),
    };
    let idish: String = workflow_id
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .take(12)
        .collect();
    let name = format!("civitai-video-{idish}-{}.{}", uuidish(), ext);
    let file = kawai_office::store::import_as(
        user_id,
        &name,
        &bytes,
        kawai_office::store::ArtifactKind::Video,
        "civitai",
        None,
    )
    .map_err(|e| format!("gagal menyimpan {name}: {e}"))?;
    let mut thumbnail_file_id = None;
    if let Some(thumb) = thumbnail_url.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
        match civitai::download_bytes(thumb).await {
            Ok(bytes) => {
                let tname = format!("civitai-video-{idish}-thumb.jpg");
                if let Ok(file) = kawai_office::store::import_as(
                    user_id,
                    &tname,
                    &bytes,
                    kawai_office::store::ArtifactKind::Image,
                    "civitai",
                    None,
                ) {
                    thumbnail_file_id = Some(file.id);
                }
            }
            // Poster is best-effort — the <video> element renders its own
            // first frame when the thumbnail is missing.
            Err(e) => eprintln!("civitai: thumbnail unduh gagal: {e}"),
        }
    }
    // Batched jobs (LTX): import the extra clips after the primary. A failed
    // extra clip is logged, not fatal — the primary result still lands.
    let mut additional = Vec::new();
    for (i, url) in additional_urls.iter().enumerate() {
        if url.trim().is_empty() {
            continue;
        }
        match import_video_file(user_id, &workflow_id, url, i + 2).await {
            Ok(saved) => additional.push(saved),
            Err(e) => eprintln!("civitai: klip tambahan {} gagal: {e}", i + 2),
        }
    }
    Ok(SavedVideo {
        file_id: file.id,
        name,
        thumbnail_file_id,
        additional,
    })
}

/// Download one video URL into the store (shared by primary + batch clips).
async fn import_video_file(
    user_id: &str,
    workflow_id: &str,
    video_url: &str,
    ordinal: usize,
) -> Result<SavedVideo, String> {
    let bytes = civitai::download_bytes(video_url.trim())
        .await
        .map_err(|e| format!("unduh video gagal: {e}"))?;
    let ext = match video_url.split('?').next().and_then(|p| {
        p.rsplit('.')
            .next()
            .map(|e| e.to_ascii_lowercase())
    }) {
        Some(e) if e == "webm" || e == "mov" || e == "m4v" => e,
        _ => "mp4".to_string(),
    };
    let idish: String = workflow_id
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .take(12)
        .collect();
    // `civitai-video-<id>-<n>.<ext>` — the ext decides the ArtifactKind,
    // the uuid suffix only uniquifies the stem.
    let name = format!(
        "civitai-video-{idish}-{ordinal}.{}.{}",
        uuidish(),
        ext
    );
    let file = kawai_office::store::import_as(
        user_id,
        &name,
        &bytes,
        kawai_office::store::ArtifactKind::Video,
        "civitai",
        None,
    )
    .map_err(|e| format!("gagal menyimpan {name}: {e}"))?;
    Ok(SavedVideo {
        file_id: file.id,
        name,
        thumbnail_file_id: None,
        additional: Vec::new(),
    })
}

// ── Civitai MUSIC generation (txt2music — workflows API) ───────────────────
//
// Same op shapes as the video lane. Simple mode drafts the structured fields
// (caption/lyrics, or lyrics/musicDescription/bpm/key on ACE) through the
// remote-llm pool — mirroring civitai's own chatCompletion drafting step
// (`music-concept.ts`, prompts quoted verbatim) — then submits custom-mode
// steps, so the orchestrator runs one step fewer.

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct MusicGenRequest {
    pub ecosystem: String,
    /// "simple" (one prompt, drafted here) | "custom" (direct fields).
    #[serde(default)]
    pub mode: Option<String>,
    /// Sonilo only: "music" (default) | "soundEffect".
    #[serde(default)]
    pub operation: Option<String>,
    /// Simple-mode prompt (the drafting input).
    #[serde(default)]
    pub prompt: Option<String>,
    /// MiniMax/ACE music description; Sonilo prompt (custom mode).
    #[serde(default)]
    pub caption: Option<String>,
    #[serde(default)]
    pub lyrics: Option<String>,
    /// YuE2: ABC score.
    #[serde(default)]
    pub abc: Option<String>,
    /// YuE2: "full" (default) | "melody" | "off".
    #[serde(default)]
    pub score_mode: Option<String>,
    #[serde(default)]
    pub steps: Option<i64>,
    /// ACE: 40–200.
    #[serde(default)]
    pub bpm: Option<i64>,
    /// ACE: musical key.
    #[serde(default)]
    pub key: Option<String>,
    #[serde(default)]
    pub instrumental_weight: Option<f64>,
    #[serde(default)]
    pub vocal_weight: Option<f64>,
    #[serde(default)]
    pub cfg_scale: Option<f64>,
    /// ACE variant: "xl-turbo" (default) | "turbo" | "xl-sft" | "xl-base" | "base".
    #[serde(default)]
    pub model: Option<String>,
    /// ACE cover image (URL / data URL / base64).
    #[serde(default)]
    pub cover_image: Option<String>,
    /// Seconds (Sonilo soundEffect takes 0.5 steps).
    #[serde(default)]
    pub duration: Option<f64>,
    #[serde(default)]
    pub seed: Option<i64>,
}

impl MusicGenRequest {
    fn is_simple(&self) -> bool {
        self.mode.as_deref() == Some("simple")
    }

    fn to_params(&self) -> civitai::MusicGenParams {
        civitai::MusicGenParams {
            ecosystem: self.ecosystem.clone(),
            mode: self.mode.clone(),
            operation: self.operation.clone(),
            caption: self.caption.clone(),
            lyrics: self.lyrics.clone(),
            abc: self.abc.clone(),
            score_mode: self.score_mode.clone(),
            steps: self.steps,
            bpm: self.bpm,
            key: self.key.clone(),
            instrumental_weight: self.instrumental_weight,
            vocal_weight: self.vocal_weight,
            cfg_scale: self.cfg_scale,
            model: self.model.clone(),
            cover_image: self.cover_image.clone(),
            duration: self.duration,
            seed: self.seed,
        }
    }
}

/// civitai's simple-mode drafting contract for models that take caption +
/// lyrics (`music-concept.ts` — MiniMax reads the caption as three labelled
/// sections; the shape is prescribed, not left to the model).
const MUSIC_CONCEPT_SYSTEM: &str = "You write song concepts for a music generation model. The caption must be a structured description with three labelled sections — Global Metadata (genre, subgenre, BPM, key, scale, emotional progression, production profile), Vocal Details (vocal gender, timbre, performance style, harmony, effects) and Arrangement (primary and secondary instruments, section-level evolution, groove, bass, percussion, textures). The lyrics must use section markers such as [Intro], [Verse], [Pre-Chorus], [Chorus], [Bridge] and [Outro]. Respond with JSON {\"caption\": string, \"lyrics\": string}.";

/// ACE's shorter simple-mode drafting contract (its own system prompt +
/// JSON shape — lyrics/description/bpm/key).
const ACE_CONCEPT_SYSTEM: &str = "You write short song concepts. Respond with JSON {\"lyrics\": string, \"musicDescription\": string, \"bpm\": integer (40-200), \"key\": string}.";

/// Resolve simple mode → final content fields: one cloud one-shot drafts
/// caption/lyrics (MiniMax/YuE2) or lyrics/musicDescription/bpm/key (ACE)
/// from the user's prompt, mirroring civitai's own chatCompletion drafting
/// step. Duration shapes the drafting ask, matching civitai's user message.
async fn finalize_request(req: &MusicGenRequest) -> Result<civitai::MusicGenParams, String> {
    let ecosystem = civitai::registry::music_ecosystem(&req.ecosystem)
        .ok_or_else(|| format!("ecosystem music '{}' tidak dikenal", req.ecosystem))?
        .key;
    let duration = req.duration.unwrap_or_else(|| {
        let eco = civitai::registry::music_ecosystem(&req.ecosystem).expect("checked above");
        let op = match req.operation.as_deref() {
            Some("soundEffect") => "soundEffect",
            _ => "music",
        };
        registry_duration_default(eco, op)
    });

    let mut final_req = MusicGenRequest {
        ecosystem: req.ecosystem.clone(),
        mode: Some("custom".into()),
        operation: req.operation.clone(),
        prompt: req.prompt.clone(),
        caption: req.caption.clone(),
        lyrics: req.lyrics.clone(),
        abc: req.abc.clone(),
        score_mode: req.score_mode.clone(),
        steps: req.steps,
        bpm: req.bpm,
        key: req.key.clone(),
        instrumental_weight: req.instrumental_weight,
        vocal_weight: req.vocal_weight,
        cfg_scale: req.cfg_scale,
        model: req.model.clone(),
        cover_image: req.cover_image.clone(),
        duration: req.duration,
        seed: req.seed,
    };

    if req.is_simple() && ecosystem != "sonilo" {
        let prompt = req
            .prompt
            .as_deref()
            .map(str::trim)
            .filter(|p| !p.is_empty())
            .ok_or_else(|| "prompt wajib diisi untuk mode simple".to_string())?;
        let (system, task, role) = if ecosystem == "ace" {
            (
                ACE_CONCEPT_SYSTEM,
                format!(
                    "Write a {duration}-second song. {prompt}. Output JSON with lyrics, musicDescription, bpm (40-200), key."
                ),
                "music-concept-ace",
            )
        } else {
            (
                MUSIC_CONCEPT_SYSTEM,
                format!(
                    "Write a song of at most {duration} seconds. {prompt}. Output JSON with caption and lyrics."
                ),
                "music-concept",
            )
        };
        let answer = remote_llm::reason::reason_in(system, &task, role, None, None)
            .await
            .map_err(|e| format!("gagal menyusun konsep lagu: {e}"))?;
        let parsed: serde_json::Value = serde_json::from_str(&remote_llm::reason::extract_json(
            &answer,
        ))
        .map_err(|e| format!("konsep lagu dari model tidak valid: {e}"))?;
        if ecosystem == "ace" {
            final_req.caption = Some(
                parsed
                    .get("musicDescription")
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .to_string(),
            );
            final_req.lyrics = Some(
                parsed
                    .get("lyrics")
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .to_string(),
            );
            final_req.bpm = parsed.get("bpm").and_then(|v| v.as_i64());
            final_req.key = parsed
                .get("key")
                .and_then(|v| v.as_str())
                .map(str::to_string);
        } else {
            final_req.caption = Some(
                parsed
                    .get("caption")
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .to_string(),
            );
            final_req.lyrics = Some(
                parsed
                    .get("lyrics")
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .to_string(),
            );
        }
    }

    // Sonilo takes ONE prompt and the panel sends it as `prompt` — the crate
    // carries it in `caption` (its single content field).
    if ecosystem == "sonilo" {
        let prompt = final_req
            .prompt
            .take()
            .or(final_req.caption.take())
            .unwrap_or_default();
        final_req.caption = Some(prompt);
    }

    Ok(final_req.to_params())
}

/// Sonilo's soundEffect default differs from the ecosystem default.
fn registry_duration_default(
    eco: &civitai::registry::MusicEcosystem,
    operation: &str,
) -> f64 {
    let (_, _, default, _) = civitai::registry::music_duration_bounds(eco, operation);
    default
}

/// Free cost estimate (whatif). Simple mode drafts first — the price of the
/// music step does not depend on the drafted text, so this matches what
/// submit will spend.
pub async fn civitai_music_cost(req: MusicGenRequest) -> Result<VideoCostView, String> {
    let key = require_key()?;
    let params = finalize_request(&req).await?;
    let est = civitai::whatif_music_gen(&key, &params).await?;
    Ok(VideoCostView {
        total_buzz: est.total_buzz,
        total_tokens: buzz_to_tokens(est.total_buzz),
        ready: est.ready,
        warnings: est.warnings,
    })
}

