#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SavedAudio {
    pub file_id: String,
    pub name: String,
}

/// Download the finished track (SIGNED, EXPIRING URL — fetch once) into the
/// office store as `ArtifactKind::Audio`. Idempotence is the CALLER's job,
/// same as the video lane.
pub async fn civitai_music_fetch(
    user_id: &str,
    workflow_id: String,
    audio_url: String,
) -> Result<SavedAudio, String> {
    let _ = require_key()?; // same baked identity; the URL itself carries the signature
    let workflow_id = workflow_id.trim().to_string();
    if workflow_id.is_empty() || audio_url.trim().is_empty() {
        return Err("workflowId dan audioUrl wajib diisi".into());
    }
    let bytes = civitai::download_bytes(audio_url.trim())
        .await
        .map_err(|e| format!("unduh audio gagal: {e}"))?;
    // Signed URLs end in the real container extension (wav/mp3/m4a/...).
    let ext = match audio_url.split('?').next().and_then(|p| {
        p.rsplit('.')
            .next()
            .map(|e| e.to_ascii_lowercase())
    }) {
        Some(e)
            if matches!(
                e.as_str(),
                "mp3" | "wav" | "m4a" | "aac" | "ogg" | "oga" | "flac"
            ) =>
        {
            e
        }
        _ => "mp3".to_string(),
    };
    let idish: String = workflow_id
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .take(12)
        .collect();
    let name = format!("civitai-music-{idish}-{}.{}", uuidish(), ext);
    let file = kawai_office::store::import_as(
        user_id,
        &name,
        &bytes,
        kawai_office::store::ArtifactKind::Audio,
        "civitai",
        None,
    )
    .map_err(|e| format!("gagal menyimpan {name}: {e}"))?;
    Ok(SavedAudio {
        file_id: file.id,
        name,
    })
}

// ── Civitai 3D MODEL generation (polyGen — workflows API) ──────────────────
